import { openDB, type IDBPDatabase } from 'idb';
import type { DayKey } from './dates';
import type { Habit, Tick } from './types';

const DB_NAME = 'habits';
const DB_VERSION = 1;

let dbPromise: Promise<IDBPDatabase> | null = null;

export function openDb(): Promise<IDBPDatabase> {
  if (!dbPromise) {
    dbPromise = openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        db.createObjectStore('habits', { keyPath: 'id' });
        const ticks = db.createObjectStore('ticks', { keyPath: 'id' });
        ticks.createIndex('by-habit', 'habitId');
        ticks.createIndex('by-day', 'day');
      },
    });
  }
  return dbPromise;
}

export async function listHabits(): Promise<Habit[]> {
  const db = await openDb();
  const habits = await db.getAll('habits');
  return habits.sort((a, b) => a.order - b.order || a.createdAt - b.createdAt);
}

export async function putHabit(h: Habit): Promise<void> {
  const db = await openDb();
  await db.put('habits', h);
}

